// HasIntegration applies the HasEdge predicate on the "integration" edge.
func HasIntegration() predicate.MerchantAPIEndpoint {
	return predicate.MerchantAPIEndpoint(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, IntegrationTable, IntegrationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIntegrationWith applies the HasEdge predicate on the "integration" edge with a given conditions (other predicates).
func HasIntegrationWith(preds ...predicate.MerchantIntegration) predicate.MerchantAPIEndpoint {
	return predicate.MerchantAPIEndpoint(func(s *sql.Selector) {
		step := newIntegrationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MerchantAPIEndpoint) predicate.MerchantAPIEndpoint {
	return predicate.MerchantAPIEndpoint(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MerchantAPIEndpoint) predicate.MerchantAPIEndpoint {
	return predicate.MerchantAPIEndpoint(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MerchantAPIEndpoint) predicate.MerchantAPIEndpoint {
	return predicate.MerchantAPIEndpoint(sql.NotPredicates(p))
}
